// Mass-production checklist (owner 2026-11-23): generated by the server from the production's own data; only the status of an item is stored.
import { errorInfo, safeFileName } from './helpers';
import { ProductionApiError } from './api';

const API = (import.meta.env.VITE_API_URL ?? 'http://localhost:8001') as string;
const enc = encodeURIComponent;
const path = (die: string, config: string) => `/api/production/${enc(die)}/${enc(config)}/checklist`;

export { CHECKLIST_STATUSES, CHECKLIST_CATEGORIES, groupItems, pick } from './checklistHelpers';
export type { ChecklistStatus, ChecklistCategory, ChecklistEvidence, ChecklistItem, ChecklistData } from './checklistHelpers';
import type { ChecklistData, ChecklistStatus } from './checklistHelpers';

async function call<T>(method: string, url: string, body?: unknown): Promise<T> {
  const r = await fetch(`${API}${url}`, { method, headers: body === undefined ? undefined : { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : JSON.stringify(body) });
  const j = await r.json().catch(() => null);
  if (!r.ok) { const e = errorInfo(r.status, j); throw new ProductionApiError(r.status, e.code, e.message); }
  return j as T;
}

export const checklistApi = {
  get: (die: string, config: string) => call<ChecklistData>('GET', path(die, config)),
  setStatus: (die: string, config: string, key: string, status: ChecklistStatus, evidence?: { doc_id: string | null; note: string }) =>
    call<ChecklistItem>('PUT', path(die, config), { key, status, ...(evidence ? { evidence } : {}) }),
  /** The Excel export (EN + 中文); an export only, nothing can be uploaded back. */
  downloadXlsx: async (die: string, config: string): Promise<void> => {
    const r = await fetch(`${API}${path(die, config)}.xlsx`);
    if (!r.ok) throw new ProductionApiError(r.status, null, `HTTP ${r.status}`);
    const url = URL.createObjectURL(await r.blob());
    const a = document.createElement('a');
    a.href = url; a.download = safeFileName(`${die}_${config}_checklist.xlsx`);
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 10_000);
  },
};
